// ---------------------------------------------------------------------------

const { resolveExpr, resolveIdentifier, annotateExpr } = require('../common/expr-resolve');

// Comment stripping just thorough enough for #define/const scanning - block
// and line comments only, no string-literal awareness needed (these
// declarations never contain one).
function stripComments(text) {
    return text.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/.*$/gm, '');
}

// sourceFiles: the Map<path, content> from dxil-metadata.js's
// getSourceFiles() - every file dxc embedded, not just the one containing
// the node function being resolved (a constant can be declared in a
// utilities/ or structs/ file the node's own file merely #includes).
function collectConstants(sourceFiles) {
    const table = new Map();
    for (const content of sourceFiles.values()) {
        const stripped = stripComments(content);

        const defineRe = /^[ \t]*#define[ \t]+([A-Za-z_]\w*)[ \t]+(.+?)[ \t]*$/gm;
        let m;
        while ((m = defineRe.exec(stripped)) !== null) {
            table.set(m[1], m[2].trim());
        }

        const constRe = /static\s+const\s+[\w:<>]+\s+([A-Za-z_]\w*)\s*=\s*([^;]+);/g;
        while ((m = constRe.exec(stripped)) !== null) {
            table.set(m[1], m[2].trim());
        }
    }
    return table;
}

